<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { useRoute } from "vue-router";
import { CheckCircle2, Copy, KanbanSquare, List, Pencil, Plus, RotateCcw, Search, Trash2 } from "@lucide/vue";
import StatePanel from "@/components/StatePanel.vue";
import { actionStatusLabels, effectiveActionStatus, type ActionBaseStatus, type ActionEffectiveStatus, type ActionRecord } from "@/domain/operations";
import { useOperationsStore } from "@/stores/operations";

const store=useOperationsStore();const route=useRoute();
const loading=ref(true);const search=ref("");const statusFilter=ref("all");const priorityFilter=ref("all");
const view=ref<"table"|"kanban">("table");const editorOpen=ref(false);const editing=ref<ActionRecord>({} as ActionRecord);const success=ref("");
const statuses:ActionEffectiveStatus[]=["not_started","in_progress","waiting","overdue","completed","cancelled"];
const metrics=computed(()=>{const s=store.actionSummary;return {...s,percent:s.total?Math.round((s.completed/s.total)*100):0};});
const filtered=computed(()=>store.actions.filter((action)=>{const effective=effectiveActionStatus(action);const text=JSON.stringify(action).toLocaleLowerCase("pt-BR");return(!search.value||text.includes(search.value.toLocaleLowerCase("pt-BR")))&&(statusFilter.value==="all"||effective===statusFilter.value)&&(priorityFilter.value==="all"||action.priority===priorityFilter.value);}));
const byStatus=(status:ActionEffectiveStatus)=>filtered.value.filter((action)=>effectiveActionStatus(action)===status);
const today=()=>new Date().toISOString().slice(0,10);
function nextNumber(){return `AP-${String(store.actions.length+1).padStart(4,"0")}`;}
function blank():ActionRecord{return{id:store.uid("action"),number:nextNumber(),title:"",problem:"",originModule:"Ações",cause:"",countermeasure:"",owner:"",priority:"medium",status:"not_started",progress:0,openedAt:today(),dueAt:today(),expectedImpact:"",evidence:"",notes:"",updatedAt:new Date().toISOString(),processId:typeof route.query.processId==="string"?route.query.processId:undefined,layoutNodeId:typeof route.query.layoutNodeId==="string"?route.query.layoutNodeId:undefined};}
function openEditor(action?:ActionRecord){editing.value=structuredClone(action??blank());editorOpen.value=true;}
function save(){editing.value.progress=Math.min(100,Math.max(0,Number(editing.value.progress)));if(editing.value.status==="completed"){editing.value.progress=100;editing.value.completedAt??=today();}store.upsertAction(editing.value);editorOpen.value=false;success.value="Ação salva com sucesso na persistência local.";}
function conclude(action:ActionRecord){store.upsertAction({...action,status:"completed",progress:100,completedAt:today()});}
function reopen(action:ActionRecord){store.upsertAction({...action,status:"in_progress",completedAt:undefined,progress:Math.min(action.progress,99)});}
function remove(action:ActionRecord){if(!window.confirm(`Excluir a ação ${action.number}? Esta operação não poderá ser desfeita.`))return;store.remove("action",action.id);success.value="Ação excluída da persistência local.";}
function entity(action:ActionRecord){return store.products.find(p=>p.id===action.productId)?.code||store.processes.find(p=>p.id===action.processId)?.name||store.resources.find(r=>r.id===action.resourceId)?.name||action.layoutNodeId||"—";}
function statusLabel(action:ActionRecord){return actionStatusLabels[effectiveActionStatus(action)];}
function priorityLabel(priority:ActionRecord["priority"]){return({low:"Baixa",medium:"Média",high:"Alta",critical:"Crítica"})[priority];}
watch([search,statusFilter,priorityFilter,view],()=>localStorage.setItem("mifc-digital:prompt-7:filters:actions",JSON.stringify({search:search.value,status:statusFilter.value,priority:priorityFilter.value,view:view.value})));
onMounted(()=>{store.hydrate();view.value=store.settings.defaultActionsView;const raw=localStorage.getItem("mifc-digital:prompt-7:filters:actions");if(raw){try{const saved=JSON.parse(raw);search.value=saved.search??"";statusFilter.value=saved.status??"all";priorityFilter.value=saved.priority??"all";view.value=saved.view??view.value;}catch{/* ignora filtro inválido */}}if(route.query.new==="1"||route.query.processId||route.query.layoutNodeId)openEditor();loading.value=false;});
</script>

<template><main class="page actions-page"><header class="page-heading"><div><p class="eyebrow">MIFC ACTION PLAN 2026</p><h1>Plano de Ações</h1><p>Contramedidas vinculadas a produtos, processos, recursos e nós do Layout.</p></div><div class="page-actions"><div class="view-toggle"><button :class="{active:view==='table'}" @click="view='table'"><List :size="16"/>Tabela</button><button :class="{active:view==='kanban'}" @click="view='kanban'"><KanbanSquare :size="16"/>Kanban</button></div><button class="button button-primary" @click="openEditor()"><Plus :size="16"/>Nova ação</button></div></header>
  <StatePanel v-if="loading" state="loading"/><template v-else>
    <div v-if="success" class="context-banner">{{ success }}</div>
    <section class="metrics"><article><small>Total de ações</small><strong>{{ metrics.total }}</strong></article><article><small>Abertas</small><strong>{{ metrics.open }}</strong></article><article><small>Em andamento</small><strong>{{ metrics.inProgress }}</strong></article><article class="risk"><small>Atrasadas</small><strong>{{ metrics.overdue }}</strong></article><article class="done"><small>Concluídas</small><strong>{{ metrics.completed }}</strong></article><article><small>Percentual concluído</small><strong>{{ metrics.percent }}%</strong></article></section>
    <section class="card filters"><div><Search :size="16"/><input v-model="search" placeholder="Pesquisar número, título, responsável..."/></div><select v-model="statusFilter"><option value="all">Todos os status</option><option v-for="status in statuses" :key="status" :value="status">{{ actionStatusLabels[status] }}</option></select><select v-model="priorityFilter"><option value="all">Todas as prioridades</option><option value="low">Baixa</option><option value="medium">Média</option><option value="high">Alta</option><option value="critical">Crítica</option></select></section>
    <StatePanel v-if="!filtered.length" state="empty" title="Nenhuma ação encontrada" message="Crie a primeira ação ou altere os filtros."/>
    <section v-else-if="view==='table'" class="card table-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Número / título</th><th>Origem</th><th>Vínculo</th><th>Responsável</th><th>Prioridade</th><th>Status</th><th>Progresso</th><th>Prazo</th><th>Ações</th></tr></thead><tbody><tr v-for="action in filtered" :key="action.id"><td><strong>{{ action.number }}</strong><small>{{ action.title }}</small></td><td>{{ action.originModule }}</td><td>{{ entity(action) }}</td><td>{{ action.owner||'—' }}</td><td><span class="priority" :class="action.priority">{{ priorityLabel(action.priority) }}</span></td><td><span class="status" :class="effectiveActionStatus(action)">{{ statusLabel(action) }}</span></td><td><div class="progress"><i :style="{width:`${action.progress}%`}"></i></div><small>{{ action.progress }}%</small></td><td>{{ new Date(`${action.dueAt}T12:00:00`).toLocaleDateString('pt-BR') }}</td><td class="row-actions"><button title="Editar" @click="openEditor(action)"><Pencil :size="15"/></button><button title="Duplicar" @click="store.duplicateAction(action.id)"><Copy :size="15"/></button><button v-if="action.status!=='completed'" title="Concluir" @click="conclude(action)"><CheckCircle2 :size="15"/></button><button v-else title="Reabrir" @click="reopen(action)"><RotateCcw :size="15"/></button><button class="danger" title="Excluir" @click="remove(action)"><Trash2 :size="15"/></button></td></tr></tbody></table></div></section>
    <section v-else class="kanban"><article v-for="status in statuses" :key="status" class="kanban-column"><header><strong>{{ actionStatusLabels[status] }}</strong><span>{{ byStatus(status).length }}</span></header><div class="kanban-list"><button v-for="action in byStatus(status)" :key="action.id" class="action-card" @click="openEditor(action)"><small>{{ action.number }} · {{ priorityLabel(action.priority) }}</small><strong>{{ action.title }}</strong><span>{{ action.owner||'Sem responsável' }}</span><div class="progress"><i :style="{width:`${action.progress}%`}"></i></div><em>Prazo {{ new Date(`${action.dueAt}T12:00:00`).toLocaleDateString('pt-BR') }}</em></button><p v-if="!byStatus(status).length">Nenhuma ação</p></div></article></section>
  </template>
  <div v-if="editorOpen" class="dialog-backdrop" @click.self="editorOpen=false"><section class="action-dialog" role="dialog" aria-modal="true"><header><div><small>PLANO DE AÇÕES</small><h2>{{ editing.number }}</h2></div><button @click="editorOpen=false">×</button></header><form @submit.prevent="save"><label>Número<input v-model.trim="editing.number" required/></label><label class="wide">Título<input v-model.trim="editing.title" required/></label><label class="wide">Problema ou oportunidade<textarea v-model.trim="editing.problem" rows="2" required></textarea></label><label>Módulo de origem<select v-model="editing.originModule"><option>Ações</option><option>Layout</option><option>Produtos</option><option>Processos</option><option>Recursos</option><option>Capacidade</option><option>Logística</option></select></label><label>Produto<select v-model="editing.productId"><option :value="undefined">Sem vínculo</option><option v-for="item in store.products" :key="item.id" :value="item.id">{{ item.code }} · {{ item.description }}</option></select></label><label>Processo<select v-model="editing.processId"><option :value="undefined">Sem vínculo</option><option v-for="item in store.processes" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Recurso<select v-model="editing.resourceId"><option :value="undefined">Sem vínculo</option><option v-for="item in store.resources" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Nó do Layout<input v-model.trim="editing.layoutNodeId" placeholder="Ex.: node-stamp"/></label><label>Responsável<input v-model.trim="editing.owner"/></label><label>Prioridade<select v-model="editing.priority"><option value="low">Baixa</option><option value="medium">Média</option><option value="high">Alta</option><option value="critical">Crítica</option></select></label><label>Status<select v-model="editing.status"><option value="not_started">Não iniciada</option><option value="in_progress">Em andamento</option><option value="waiting">Aguardando</option><option value="completed">Concluída</option><option value="cancelled">Cancelada</option></select></label><label>Progresso (%)<input v-model.number="editing.progress" type="number" min="0" max="100"/></label><label>Data de abertura<input v-model="editing.openedAt" type="date" required/></label><label>Prazo<input v-model="editing.dueAt" type="date" required/></label><label v-if="editing.status==='completed'">Data de conclusão<input v-model="editing.completedAt" type="date"/></label><label class="wide">Causa<textarea v-model.trim="editing.cause" rows="2"></textarea></label><label class="wide">Ação ou contramedida<textarea v-model.trim="editing.countermeasure" rows="2" required></textarea></label><label class="wide">Impacto esperado<textarea v-model.trim="editing.expectedImpact" rows="2"></textarea></label><label class="wide">Evidência<input v-model.trim="editing.evidence" placeholder="Descrição ou caminho da evidência"/></label><label class="wide">Observações<textarea v-model.trim="editing.notes" rows="2"></textarea></label><footer class="wide"><button class="button button-secondary" type="button" @click="editorOpen=false">Cancelar</button><button class="button button-primary">Salvar ação</button></footer></form></section></div>
</main></template>

<style scoped>
.actions-page{display:grid;gap:16px}.eyebrow{margin:0 0 5px!important;color:var(--brand-blue);font-size:10px!important;font-weight:700;letter-spacing:.08em}.view-toggle{display:flex;padding:3px;border:1px solid var(--border-subtle);border-radius:7px;background:#fff}.view-toggle button{display:flex;min-height:32px;align-items:center;gap:6px;padding:0 10px;border:0;border-radius:5px;background:transparent;color:var(--text-secondary)}.view-toggle button.active{background:var(--brand-blue-soft);color:var(--brand-blue)}.context-banner{padding:12px 15px;border:1px solid #b9e5c8;border-radius:8px;background:#effaf3;color:#15713a;font-size:12px}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.metrics article{display:grid;gap:7px;padding:15px;border:1px solid var(--border-subtle);border-radius:9px;background:#fff}.metrics small{color:var(--text-secondary)}.metrics strong{font-size:24px}.metrics .risk strong{color:var(--danger)}.metrics .done strong{color:#168246}.filters{display:flex;gap:10px;padding:12px}.filters>div{display:flex;flex:1;align-items:center;gap:8px;padding:0 11px;border:1px solid var(--border-subtle);border-radius:6px}.filters input{width:100%;height:36px;border:0;outline:0}.filters select{min-width:170px;border:1px solid var(--border-subtle);border-radius:6px;background:#fff;padding:0 9px}.table-card{overflow:hidden}.data-table td strong,.data-table td small{display:block}.data-table td small{margin-top:4px;color:var(--text-tertiary)}.priority,.status{display:inline-flex;padding:4px 7px;border-radius:999px;background:#edf3ff;color:#205bd8;font-size:9px;font-weight:700}.priority.high,.priority.critical,.status.overdue{background:#fff0ef;color:#b32922}.priority.medium,.status.waiting{background:#fff5e4;color:#996000}.status.completed{background:#eaf8ef;color:#14753a}.progress{width:76px;height:5px;overflow:hidden;border-radius:5px;background:#e7ebf1}.progress i{display:block;height:100%;background:var(--brand-blue)}.row-actions{white-space:nowrap}.row-actions button{display:inline-grid;width:28px;height:28px;place-items:center;border:0;border-radius:5px;background:transparent;color:var(--text-secondary)}.row-actions button:hover{background:var(--brand-blue-soft);color:var(--brand-blue)}.row-actions .danger:hover{background:#fff0ef;color:var(--danger)}.kanban{display:grid;grid-template-columns:repeat(6,minmax(210px,1fr));gap:10px;overflow-x:auto;padding-bottom:10px}.kanban-column{min-height:430px;border:1px solid var(--border-subtle);border-radius:9px;background:#f7f9fc}.kanban-column>header{display:flex;align-items:center;justify-content:space-between;padding:12px;border-bottom:1px solid var(--border-subtle)}.kanban-column>header span{display:grid;width:23px;height:23px;place-items:center;border-radius:50%;background:#fff;font-size:10px}.kanban-list{display:grid;gap:8px;padding:8px}.kanban-list>p{color:var(--text-tertiary);font-size:11px;text-align:center}.action-card{display:grid;gap:7px;padding:11px;border:1px solid var(--border-subtle);border-radius:7px;background:#fff;color:var(--text-primary);text-align:left;box-shadow:0 2px 6px rgba(15,29,52,.04)}.action-card small,.action-card span,.action-card em{color:var(--text-tertiary);font-size:9px;font-style:normal}.dialog-backdrop{position:fixed;z-index:120;inset:0;display:grid;place-items:center;padding:20px;background:rgba(15,29,52,.42)}.action-dialog{display:flex;width:min(920px,96vw);max-height:92vh;flex-direction:column;overflow:hidden;border-radius:12px;background:#fff;box-shadow:0 22px 70px rgba(0,0,0,.25)}.action-dialog>header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--border-subtle)}.action-dialog h2{margin:3px 0 0}.action-dialog header small{color:var(--brand-blue);font-weight:700}.action-dialog header button{border:0;background:transparent;font-size:26px}.action-dialog form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;overflow:auto;padding:20px}.action-dialog label{display:grid;gap:5px;color:var(--text-secondary);font-size:11px;font-weight:600}.action-dialog input,.action-dialog select,.action-dialog textarea{min-height:38px;padding:8px;border:1px solid var(--border-subtle);border-radius:6px;background:#fff;font:inherit}.wide{grid-column:1/-1}.action-dialog footer{display:flex;justify-content:flex-end;gap:8px}.actions-page :deep(.state-panel){min-height:250px}@media(max-width:1100px){.metrics{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.metrics{grid-template-columns:repeat(2,1fr)}.filters{align-items:stretch;flex-direction:column}.filters select{min-height:38px}.action-dialog form{grid-template-columns:1fr}.wide{grid-column:auto}}
</style>
